type UserId = string & { [userIdBrand]: true };

// Use explicit type parameter:
mockUser(nanoid<UserId>());

interface User {
  id: UserId;
  name: string;
}

const user: User = {
  // Automatically casts to UserId:
  id: nanoid(),
  name: "Alice",
};
```

